<template>
  <section class="writing-room">
    <header><div><span>WRITING ROOM</span><h3>Let the thought<br />become language.</h3><p>A quiet place for a manifesto, poem, plan, script, letter, or the first page of something larger.</p></div><b>{{ wordCount }}<small>WORDS</small></b></header>
    <div class="writing-surface"><label>WORK TITLE<input v-model.trim="title" maxlength="80" placeholder="Name the piece when it is ready" /></label><textarea v-model="body" maxlength="20000" placeholder="Begin with the sentence that has been waiting for you…"></textarea><span>{{ body.length.toLocaleString() }} CHARACTERS</span></div>
    <footer><p>{{ message || 'Nothing is published. This room belongs to the work while it is becoming.' }}</p><div><button type="button" @click="clear">Clear</button><button class="keep" type="button" @click="save">Keep in TOP ↗</button></div></footer>
  </section>
</template>

<script setup lang="ts">
import { computed, onMounted, ref } from "vue";

const storageKey = "top-writing-room-v1";
const title = ref("");
const body = ref("");
const message = ref("");
const wordCount = computed(() => body.value.trim() ? body.value.trim().split(/\s+/).length : 0);

function save(): void { if (!title.value && !body.value.trim()) { message.value = "WRITE SOMETHING FIRST"; return; } try { localStorage.setItem(storageKey, JSON.stringify({ title: title.value, body: body.value })); message.value = "WRITING HELD LOCALLY"; } catch { message.value = "LOCAL STORAGE IS FULL"; } }
function clear(): void { title.value = ""; body.value = ""; try { localStorage.removeItem(storageKey); message.value = "PAGE CLEARED"; } catch { message.value = "PAGE CLEARED FROM THIS VIEW"; } }
onMounted(() => { try { const saved = JSON.parse(localStorage.getItem(storageKey) ?? "null") as { title?: string; body?: string } | null; title.value = saved?.title ?? ""; body.value = saved?.body ?? ""; } catch { /* Start with an honest blank page. */ } });
</script>

<style scoped>
.writing-room { background:linear-gradient(145deg,rgba(50,28,68,.8),rgba(10,7,25,.93)); border:1px solid rgba(255,114,189,.32); border-radius:26px 26px 7px 26px; box-shadow:inset 0 1px rgba(255,232,248,.07),0 25px 75px rgba(0,0,0,.25); grid-column:span 3; overflow:hidden; padding:clamp(25px,4vw,46px); position:relative; }.writing-room::after { background:radial-gradient(circle,rgba(255,114,189,.17),transparent 68%); content:""; height:430px; position:absolute; right:-220px; top:-250px; width:430px; }.writing-room header { align-items:flex-start; display:flex; justify-content:space-between; position:relative; }.writing-room header > div > span { color:var(--top-pink); font-family:var(--top-mono); font-size:9px; letter-spacing:.17em; }.writing-room h3 { font-family:var(--top-display); font-size:clamp(31px,3.8vw,54px); font-weight:750; letter-spacing:-.08em; line-height:.89; margin:13px 0; }.writing-room header p { color:var(--top-muted); line-height:1.65; max-width:610px; }.writing-room header b { align-items:center; border:1px solid rgba(255,114,189,.47); border-radius:50%; color:var(--top-pink); display:flex; flex-direction:column; font-family:var(--top-display); font-size:24px; height:66px; justify-content:center; width:66px; }.writing-room header b small { font-family:var(--top-mono); font-size:6px; letter-spacing:.13em; margin-top:3px; }.writing-surface { background:linear-gradient(145deg,rgba(255,255,255,.055),rgba(255,255,255,.018)); border:1px solid rgba(255,188,224,.14); border-radius:18px 18px 5px 18px; margin-top:26px; padding:clamp(20px,3vw,34px); position:relative; }.writing-surface label { color:rgba(247,207,232,.58); display:block; font-family:var(--top-mono); font-size:8px; letter-spacing:.14em; }.writing-surface input { background:transparent; border:0; border-bottom:1px solid rgba(255,179,219,.18); color:var(--top-ink); display:block; font-family:var(--top-display); font-size:clamp(23px,3vw,34px); font-weight:700; letter-spacing:-.05em; margin-top:7px; outline:0; padding:0 0 14px; width:100%; }.writing-surface textarea { background:transparent; border:0; color:rgba(237,242,255,.91); display:block; font-family:var(--top-body); font-size:16px; line-height:1.85; min-height:350px; outline:0; padding:24px 0; resize:vertical; width:100%; }.writing-surface textarea::placeholder { color:rgba(206,212,244,.32); }.writing-surface > span { bottom:19px; color:rgba(229,206,241,.34); font-family:var(--top-mono); font-size:8px; letter-spacing:.12em; position:absolute; right:23px; }.writing-room footer { align-items:center; border-top:1px solid rgba(255,170,218,.13); display:flex; gap:16px; justify-content:space-between; margin-top:16px; padding-top:16px; position:relative; }.writing-room footer p { color:rgba(224,211,244,.54); font-size:11px; max-width:570px; }.writing-room footer div { display:flex; gap:8px; }.writing-room footer button { background:transparent; border:1px solid rgba(255,167,216,.23); border-radius:999px; color:rgba(246,228,253,.8); cursor:pointer; font-family:var(--top-mono); font-size:8px; padding:10px 13px; }.writing-room footer .keep { background:linear-gradient(110deg,var(--top-pink),var(--top-violet)); border:0; color:#0a0613; }
@media (max-width:800px) { .writing-room { grid-column:span 1; padding:24px; }.writing-room header,.writing-room footer { align-items:flex-start; flex-direction:column; }.writing-surface textarea { min-height:290px; }.writing-room footer div { width:100%; }.writing-room footer button { flex:1; } }
</style>
